// === 3. 响应式图片 + 尺寸占位防 CLS ===
function HeroImage() {
  return (
    <picture>
      <source srcSet="/hero.avif" type="image/avif" />
      <source srcSet="/hero.webp" type="image/webp" />
      <img
        src="/hero.jpg"
        alt="Hero"
        width={1200}
        height={600}  /* 明确尺寸，防 CLS */
        loading="eager"  /* LCP 图片不要 lazy */
        fetchPriority="high"  /* 提升加载优先级 */
        style={{ width: '100%', height: 'auto' }}
      />
    </picture>
  );
}

// === 4. Web Worker 计算密集任务 ===
// worker.ts
self.addEventListener('message', (e: MessageEvent<{ data: ArrayBuffer }>) => {
  const { data } = e.data;
  // 处理大 JSON 或图像数据
  const result = processHeavyData(data);
  // Transferable 零拷贝回传
  self.postMessage({ result }, [result]);
});

// 主线程
function runInWorker(payload: ArrayBuffer): Promise<ArrayBuffer> {
  return new Promise((resolve, reject) => {
    const worker = new Worker(new URL('./worker.ts', import.meta.url));
    worker.onmessage = (e) => resolve(e.data.result);
    worker.onerror = reject;
    // Transferable：转移所有权，不序列化
    worker.postMessage({ data: payload }, [payload]);
  });
}

