// === 6. 虚拟列表（react-window） ===
import { FixedSizeList } from 'react-window';

function VirtualList({ items }: { items: string[] }) {
  return (
    <FixedSizeList
      height={600}
      width="100%"
      itemCount={items.length}
      itemSize={48}
    >
      {({ index, style }) => (
        <div style={style}>{items[index]}</div>
      )}
    </FixedSizeList>
  );
}

